package com.github.zzave.teambalance.api.domain.model

import java.time.Duration
import java.time.Instant
import java.util.UUID

/** The identity of a [BulletinPost]. Generated by the persistence adapter when the row is created. */
@JvmInline
value class BulletinPostId(val value: UUID) {
    override fun toString(): String = value.toString()
}

/** The Markdown of a [BulletinPost], trimmed, never blank, at most [MAX_LENGTH] characters (ADR-0050). */
@JvmInline
value class PostMarkdown private constructor(val value: String) {
    companion object {
        const val MAX_LENGTH = 5000

        fun of(raw: String): PostMarkdown {
            val markdown = raw.trim()
            require(markdown.isNotBlank()) { "A post must not be blank" }
            require(markdown.length <= MAX_LENGTH) { "A post must be at most $MAX_LENGTH characters" }
            return PostMarkdown(markdown)
        }

        /** For values read back from storage, which were validated when written. */
        fun stored(value: String) = PostMarkdown(value)
    }
}

/** What an Admin writes in a [BulletinPost], on create and on each edit. */
data class NewPostContent(
    val markdown: PostMarkdown,
    val pinned: Boolean = false,
    val showUntil: Instant? = null,
)

/** One save of an existing [BulletinPost]: who and when, not the old text (ADR-0050). */
data class PostEdit(
    val editorId: UserId,
    val editedAt: Instant,
)

/** A message an Admin posts on the Team's Bulletin Board for every Member (ADR-0050). */
data class BulletinPost(
    val id: BulletinPostId,
    val markdown: PostMarkdown,
    val authorId: UserId,
    val postedAt: Instant,
    /** Oldest first. */
    val edits: List<PostEdit> = emptyList(),
    /** Comes first on the board and shows in the strip on every page. */
    val pinned: Boolean = false,
    /** When Members stop seeing it; null shows it until it is deleted. */
    val showUntil: Instant? = null,
    /** Set when an Admin deleted it: hidden from Members, restorable until [removedAt]. */
    val deletedAt: Instant? = null,
) {
    /** When a deleted Post is removed for good; null while it is not deleted. */
    val removedAt: Instant? get() = deletedAt?.plus(RETENTION)

    companion object {
        /** How long a deleted Post can still be restored (ADR-0050). */
        val RETENTION: Duration = Duration.ofDays(14)
    }
}
